style.css:
@-moz-document domain("youtube.com") {
/* Glowing pink, purple & blue neon stars background for the top bar */
  ytd-masthead,
  ytd-masthead #container.ytd-masthead,
  ytd-masthead #background.ytd-masthead {
    background-color: #120024 !important;
    background-image: 
      url("data:image/svg+xml,%3Csvg xmlns='http://w3.org' width='180' height='90' viewBox='0 0 180 90'%3E%3Cdefs%3E%3Cfilter id='glow'%3E%3CfeGaussianBlur stdDeviation='2' result='coloredBlur'/%3E%3CfeMerge%3E%3CfeMergeNode in='coloredBlur'/%3E%3CfeMergeNode in='SourceGraphic'/%3E%3C/feMerge%3E%3C/filter%3E%3C/defs%3E%3Cg fill='none' stroke-width='1.8' filter='url(%23glow)'%3E%3Cpolygon stroke='%23ff33cc' points='30,8 35,22 50,22 38,31 42,45 30,36 18,45 22,31 10,22 25,22'/%3E%3Cpolygon stroke='%2300e5ff' points='95,40 99,51 111,51 101,58 105,69 95,62 85,69 89,58 79,51 91,51'/%3E%3Cpolygon stroke='%23b366ff' points='145,10 149,21 161,21 151,28 155,39 145,32 135,39 139,28 129,21 141,21'/%3E%3Cpolygon stroke='%23ff66e0' points='65,65 68,73 77,73 70,78 73,86 65,81 57,86 60,78 53,73 62,73'/%3E%3Cpolygon stroke='%236666ff' points='160,58 163,66 172,66 165,71 168,79 160,74 152,79 155,71 148,66 157,66'/%3E%3C/g%3E%3C/svg%3E") !important;
    background-repeat: repeat !important;
    background-size: 180px 90px !important;
  }

  ytd-masthead {
    border-bottom: 2px solid #ff66d9 !important;
    box-shadow: 0 2px 15px rgba(255, 102, 217, 0.6) !important;
  }

  /* Keep ONLY the search bar and microphone dark & glowing (no boxes around bell or profile!) */
  ytd-searchbox[mode="legacy"] #container.ytd-searchbox,
  yt-searchbox .ytSearchboxComponentInputBox,
  #voice-search-button button {
    background: rgba(18, 0, 36, 0.85) !important;
    border: 1.5px solid #ff66d9 !important;
    box-shadow: 0 0 8px rgba(255, 102, 217, 0.6) !important;
  }

  /* Comic Sans font inside the search bar */
  ytd-searchbox input#search,
  yt-searchbox input.ytSearchboxComponentInput {
    font-family: "Comic Sans MS", "Comic Sans", "Comic Neue", cursive !important;
    color: #ffccff !important;
  }
}
